// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { getPublicCollections, postPublicCollections } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const publicGetResponse = await getPublicCollections(client, headers);

    expect(getValue(publicGetResponse, "response").length, 'the caller owns no public collections').toBe(0);
    expect(getResponseValue(publicGetResponse, "response.0"), 'first index is absent').toBeNull();
    expect(getResponseValue(publicGetResponse, "error"), 'no error field').toBeNull();

    const publicPostResponse = await postPublicCollections(
        client,
        headers,
        "Skyramp Method Guard Collection",
        "Must never be created"
    );

    expect(getResponseValue(publicPostResponse, "response"), 'error message').toBe("Method not allowed.");
    expect(getResponseValue(publicPostResponse, "response.id"), 'the refused POST returns no created collection').toBeNull();
});
